parametros.consulta_graphql:
query($consulta: String!, $n: Int!) {
  rateLimit { cost remaining resetAt }
  search(query: $consulta, type: DISCUSSION, first: $n) {
    discussionCount
    pageInfo { hasNextPage endCursor }
    nodes {
      ... on Discussion {
        id
        number
        url
        title
        body
        createdAt
        updatedAt
        author { login }
        repository { nameWithOwner }
        category { name }
        isAnswered
        answerChosenAt
        upvoteCount
        comments { totalCount }
      }
    }
  }
}

